"""Write ui/form.js from shared/python/opportunity_form.py, so the funding page renders the form the API validates.

    python3 scripts/gen_form_js.py      (run by deploy.sh)
"""

import importlib.util
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
spec = importlib.util.spec_from_file_location("opportunity_form", ROOT / "shared" / "python" / "opportunity_form.py")
form = importlib.util.module_from_spec(spec)
spec.loader.exec_module(form)

(ROOT / "ui" / "form.js").write_text(
    "// Generated by scripts/gen_form_js.py from shared/python/opportunity_form.py. Do not edit by hand.\n"
    f"window.OPPORTUNITY_FORM = {json.dumps(form.ui_schema(), indent=1, ensure_ascii=False)};\n")
print(f"ui/form.js: {len(form.FIELDS)} questions in {len(form.SECTIONS)} sections")
